const nums=[488,486,485,457,449,447,437,407,385,377,376,375,371,369,333,296,292,281,278,254,239,236,235,229,219,212,208,207,190,188,176,172,171,167,158,157,153,148,146,133,132,127,123,114,112,88,77,75,68,67,46,39,36,34,24,23,22,21,19,20,2];
let issues=[];
for(let i=0;i<nums.length;i+=15){
  const rs=await Promise.all(nums.slice(i,i+15).map(issue_number=>tools.mcp__codex_apps__github_fetch_issue({repository_full_name:"seungpyoson/bolt-v2",issue_number})));
  for(const r of rs){ if(r?.structuredContent?.issue) issues.push(r.structuredContent.issue); }
}
store("low_issues",issues);
text(`stored ${issues.length} low-range issues; body chars=${issues.reduce((n,x)=>n+(x.body?.length||0),0)}`);

const issues=load("low_issues")||[];
for(const x of issues){
 const b=x.body||"";
 const open=(b.match(/-\s*\[ \]/g)||[]).length, done=(b.match(/-\s*\[[xX]\]/g)||[]).length;
 const lines=b.split(/\r?\n/).map(s=>s.trim()).filter(s=>s && /(remaining|supersed|blocked|delivered|complete|status|acceptance|close|deferred|open \/|open:|not implemented|not yet|done)/i.test(s));
 text(`#${x.issue_number} ${x.title} | boxes ${done}/${open} | ${lines.slice(0,3).map(s=>s.slice(0,220)).join(" || ")}`);
}

const issues=load("low_issues")||[];
for(const n of [485,486,371,296,229]){
 const x=issues.find(y=>y.issue_number===n); text(`===== #${n} ${x.title} =====\n${x.body}`);
}

