const issues=load("low_issues")||[];
function sections(body){
 const lines=(body||"").split(/\r?\n/), out=[];
 let take=0;
 for(let i=0;i<lines.length;i++){
   const l=lines[i];
   if(/^#{1,4}\s+/.test(l) && /(problem|scope|accept|status|remaining|expected|decision|gap|current|done|close|non-goal|deliverable|implementation|outcome)/i.test(l)){out.push(l);take=12;continue;}
   if(take>0){if(/^#{1,4}\s+/.test(l)){take=0;} else {out.push(l);take--;}}
 }
 return out.join("\n").slice(0,5000);
}
for(const n of [457,449,447,407,212,208,188,172,171,167,158,157]){
 const x=issues.find(y=>y.issue_number===n); text(`===== #${n} ${x.title} =====\n${sections(x.body)}`);
}

const issues=load("low_issues")||[];
for(const n of [449,447,407,212,188,172,167]){
 const x=issues.find(y=>y.issue_number===n); text(`===== #${n} =====\n${x.body.slice(0,9000)}`);
}

const nums=[406,360,331,455,205,279,183,186,295,294];
const rs=await Promise.all(nums.map(issue_number=>tools.mcp__codex_apps__github_fetch_issue({repository_full_name:"seungpyoson/bolt-v2",issue_number})));
for(const [i,r] of rs.entries()){
 const x=r?.structuredContent?.issue; text(`#${nums[i]} state=${x?.state} reason=${x?.state_reason} title=${x?.title}\n${(x?.body||"").slice(-1800)}`);
}

